import{c as t,Q as o,j as r,m as a}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"Financial Framework — Overview","description":"","frontmatter":{},"headers":[],"relativePath":"framework/overview.md","filePath":"framework/overview.md","lastUpdated":null}'),n={name:"framework/overview.md"};function s(i,e,d,l,c,m){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="financial-framework-—-overview" tabindex="-1">Financial Framework — Overview <a class="header-anchor" href="#financial-framework-—-overview" aria-label="Permalink to &quot;Financial Framework — Overview&quot;">​</a></h1><p>FinSight’s guidance is shaped by six durable ideas, not motivational slogans. Each becomes a calculation the Copilot can cite.</p><table tabindex="0"><thead><tr><th>Principle</th><th>Source</th><th>Where it lives in FinSight</th></tr></thead><tbody><tr><td>Pay Yourself First (≥10%)</td><td>Babylon / Ramsey</td><td>Savings rate on Today; Babylon nudge; Copilot priority #1</td></tr><tr><td>Emergency Fund (3–6 months)</td><td>Ramsey / Sethi</td><td>Quick-fill on Goals; <code>wellness_context.emergency_fund_months</code></td></tr><tr><td>Debt Snowball (smallest first)</td><td>Ramsey</td><td><code>wellness_context.debt_snowball</code> ordered by balance ASC</td></tr><tr><td>Conscious Spending (Need/Want/Saving/Investment)</td><td>Sethi</td><td><code>spending_type</code> on categories; allocation donut on Budget</td></tr><tr><td>Compound Growth (7% annual)</td><td>Hill / Kiyosaki</td><td>10/20/30-year projection on Goals</td></tr><tr><td>Behaviour over math</td><td>Housel</td><td>Nudges surface patterns, not just totals</td></tr><tr><td>Financial Journey</td><td>All</td><td><code>/journey</code> — seven milestones from stability to freedom</td></tr></tbody></table><h2 id="how-the-framework-reaches-the-user" tabindex="-1">How the framework reaches the user <a class="header-anchor" href="#how-the-framework-reaches-the-user" aria-label="Permalink to &quot;How the framework reaches the user&quot;">​</a></h2><ol><li><strong>Metrics</strong> (<code>finsight-core::metrics</code> + <code>wellness_context</code>) compute emergency-fund months, snowball order, allocation, savings rate.</li><li><strong>Prompt</strong> (<code>planner.rs::build_system_prompt</code>) embeds the framework so every LLM call is steered the same way.</li><li><strong>Screens</strong> (Today, Budget, Goals, Journey) render the same metrics with inputs and caveats exposed in the inspector.</li></ol><p>No screen invents advice. The Copilot’s job is to translate the metric into a next step: fund the emergency buffer before ambitious saving, pay the smallest debt first for momentum, keep wants from quietly eating savings.</p><p>Next: <a href="/FinSight/framework/pay-yourself-first">Pay Yourself First</a>.</p>',7)])])}const f=t(n,[["render",s]]);export{u as __pageData,f as default};
